81	// ====== 欢迎界面 ======
82	function showWelcome() {
83	  document.getElementById("app").style.display = "none";
84	  const welcome = document.getElementById("welcome-screen");
85	  welcome.style.display = "flex";
86	
87	  // 更新继续游戏按钮区域
88	  const loadSection = document.getElementById("load-section");
89	  if (loadSection) {
90	    const allSlots = getAllSlots();
91	    if (allSlots.length > 0) {
92	      // 找最新存档
93	      allSlots.sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
94	      const latest = allSlots[0];
95	      loadSection.style.display = "";
96	      loadSection.innerHTML = `
97	        <button id="btn-load-latest" class="btn btn-lg">📂 继续游戏 (第${latest.day}天, ¥${latest.cash?.toLocaleString() || 0})</button>
98	        <button id="btn-load-menu" class="btn btn-sm" style="margin-top:8px;">📋 选择存档...</button>
99	      `;
100	      document.getElementById("btn-load-latest").onclick = () =>
101	        loadExistingGame(latest.slot);
102	      document.getElementById("btn-load-menu").onclick = () =>
103	        showLoadMenuOnWelcome();
104	    } else {
105	      loadSection.style.display = "none";
106	    }
107	  }
108	
109	  document.getElementById("btn-new-game").onclick = () => startNewGame();
110	  document.getElementById("btn-skip-tutorial").onclick = () => {
111	    if (typeof markTutorialDone === "function") markTutorialDone();
112	    startNewGame();
113	  };
114	}
