70	/** 玩家卖出商品 */
71	function sellGood(goodId, qty) {
72	  const state = StateManager.getState();
73	  const good = getGoodById(goodId);
74	  if (!good) {
75	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
76	    return false;
77	  }
78	
79	  // 检查背包
80	  const existing = state.inventory.items.find((i) => i.id === goodId);
81	  if (!existing || existing.qty < qty) {
82	    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
83	    return false;
84	  }
85	
86	  const locKey = state.trade.currentLocation;
87	  let price = getCurrentPrice(locKey, goodId);
88	
89	  // 同地转卖惩罚：如果卖出地点就是购买地点，售价打7折
90	  let sameLocationPenalty = false;
91	  if (existing.boughtAt === locKey) {
92	    price = Math.round(price * 0.7 * 100) / 100;
93	    sameLocationPenalty = true;
94	  }
95	
96	  // 销售技能溢价（最高15%）
97	  const salesLvl = state.skills.sales.level || 0;
98	  const premium = Math.min(0.15, salesLvl * 0.002);
99	  const totalEarned = Math.round(price * qty * (1 + premium) * 100) / 100;
100	
101	  // 加钱
102	  state.resources.cash += totalEarned;
103	  state.resources.totalEarned += totalEarned;
104	
105	  // 从背包移除
106	  existing.qty -= qty;
107	  if (existing.qty <= 0) {
108	    state.inventory.items = state.inventory.items.filter(
109	      (i) => i.id !== goodId,
110	    );
111	  }
112	
113	  // 低买高卖时显示利润
114	  const buyPrice = getAvgBuyPrice(state, goodId); // 估算买入价
115	  let profitMsg = "";
116	  if (sameLocationPenalty) {
117	    profitMsg = " ⚠️ 同地转卖，贬值严重！";
118	  } else if (buyPrice > 0) {
119	    const profit = totalEarned - buyPrice * qty;
120	    if (profit > 0) {
121	      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
122	    } else if (profit < 0) {
123	      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
124	    }
125	  }
126	
127	  // 卖出后该商品在当地降价 1~3%
128	  const sellDelta = -(0.01 + Math.random() * 0.02);
129	  adjustPriceAfterTrade(locKey, goodId, sellDelta);
130	  const newPrice = getCurrentPrice(locKey, goodId);
131	  const priceMsg =
132	    newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : "";
133	
134	  StateManager.addMessage(
135	    `💰 卖出了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalEarned.toFixed(1)}。${profitMsg}${priceMsg}`,
136	    "success",
137	  );
138	  return true;
139	}
