141	/** 批发进货（批发市场专属） */
142	function buyWholesale(goodId, qty) {
143	  const state = StateManager.getState();
144	  const good = getGoodById(goodId);
145	  if (!good) {
146	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
147	    return false;
148	  }
149	
150	  const locKey = state.trade.currentLocation;
151	  const price = getCurrentPrice(locKey, goodId);
152	
153	  // 批发折扣：批发市场的价格 × 0.7（批量价）
154	  const wholesalePrice = Math.round(price * 0.7 * 100) / 100;
155	  const totalCost = Math.round(wholesalePrice * qty * 100) / 100;
156	
157	  // 最低起批量
158	  if (qty < 5) {
159	    StateManager.addMessage("⚠️ 批发最少购买5件。", "warning");
160	    return false;
161	  }
162	
163	  // 检查现金
164	  if (state.resources.cash < totalCost) {
165	    StateManager.addMessage(
166	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}。`,
167	      "danger",
168	    );
169	    return false;
170	  }
171	
172	  // 检查背包
173	  const currentItems = state.inventory.items.reduce(
174	    (sum, item) => sum + item.qty,
175	    0,
176	  );
177	  if (currentItems + qty > state.inventory.capacity) {
178	    StateManager.addMessage(
179	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
180	      "danger",
181	    );
182	    return false;
183	  }
184	
185	  // 扣钱
186	  state.resources.cash -= totalCost;
187	
188	  // 记录买入价（用于后续利润计算）
189	  const existing = state.inventory.items.find((i) => i.id === goodId);
190	  if (existing) {
191	    // 加权平均买入价
192	    const oldTotal = (existing.avgBuyPrice || wholesalePrice) * existing.qty;
193	    const newTotal = wholesalePrice * qty;
194	    existing.qty += qty;
195	    existing.boughtAt = locKey;
196	    existing.avgBuyPrice =
197	      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
198	  } else {
199	    state.inventory.items.push({
200	      id: goodId,
201	      qty,
202	      avgBuyPrice: wholesalePrice,
203	      boughtAt: locKey,
204	    });
205	  }
206	
207	  StateManager.addMessage(
208	    `📦 批发进货 ${qty}${good.unit}${good.name}，批发价 ¥${wholesalePrice.toFixed(1)}/件，共 ¥${totalCost.toFixed(1)}。`,
209	    "success",
210	  );
211	  return true;
212	}
