226	/** 交易后动态调价：买入涨价，卖出降价 */
227	function adjustPriceAfterTrade(locKey, goodId, delta) {
228	  const state = StateManager.getState();
229	  const good = getGoodById(goodId);
230	  if (!good) return;
231	  const prices = state.trade.goodsPrices[locKey];
232	  if (!prices) return;
233	  const oldPrice = prices[goodId] || good.basePrice;
234	  const change = oldPrice * delta;
235	  let newPrice = oldPrice + change;
236	  // 限制范围
237	  newPrice = Math.max(
238	    good.basePrice * 0.3,
239	    Math.min(good.basePrice * 5, newPrice),
240	  );
241	  newPrice = Math.round(newPrice * 100) / 100;
242	  prices[goodId] = newPrice;
243	}
244	
245	/** 获取当前地点某商品的零售价 */
246	function getCurrentPrice(locKey, goodId) {
247	  const state = StateManager.getState();
248	  const prices = state.trade.goodsPrices[locKey];
249	  if (prices && prices[goodId] !== undefined) {
250	    return prices[goodId];
251	  }
252	  const good = getGoodById(goodId);
253	  return good ? good.basePrice : 1;
254	}
255	
256	/** 获取某商品在所有地点的最低价格（用于价格对比） */
257	function getLowestPrice(goodId) {
258	  const state = StateManager.getState();
259	  let lowest = Infinity;
260	  let lowestLoc = null;
261	  for (const locKey of Object.keys(LOCATIONS)) {
262	    const prices = state.trade.goodsPrices[locKey] || {};
263	    const price = prices[goodId];
264	    if (price && price < lowest) {
265	      lowest = price;
266	      lowestLoc = locKey;
267	    }
268	  }
269	  return { price: lowest, location: lowestLoc };
270	}
271	
272	/** 获取某商品在所有地点的最高价格 */
273	function getHighestPrice(goodId) {
274	  const state = StateManager.getState();
275	  let highest = 0;
276	  let highestLoc = null;
277	  for (const locKey of Object.keys(LOCATIONS)) {
278	    const prices = state.trade.goodsPrices[locKey] || {};
279	    const price = prices[goodId];
280	    if (price && price > highest) {
281	      highest = price;
282	      highestLoc = locKey;
283	    }
284	  }
285	  return { price: highest, location: highestLoc };
286	}
287	
288	/** 估算平均买入价 */
289	function getAvgBuyPrice(state, goodId) {
290	  const item = state.inventory.items.find((i) => i.id === goodId);
291	  return item ? item.avgBuyPrice || 0 : 0;
292	}
293	
294	/** 更新所有地点所有商品的价格（每3天调用一次） */
295	function updateAllPrices(state) {
296	  for (const locKey of Object.keys(LOCATIONS)) {
297	    const loc = LOCATIONS[locKey];
298	    // 确保价格对象存在
299	    if (!state.trade.goodsPrices[locKey]) {
300	      state.trade.goodsPrices[locKey] = {};
301	    }
302	    for (const good of GOODS) {
303	      let price = good.basePrice;
304	
305	      // 1. 地点倍率
306	      if (loc.priceMod && loc.priceMod[good.id]) {
307	        price *= loc.priceMod[good.id];
308	      }
309	
310	      // 2. 随机波动 ±25%
311	      const fluctuation = 0.75 + Math.random() * 0.5;
312	      price *= fluctuation;
313	
314	      // 3. 均值回归（10%向旧价格靠拢）
315	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
316	      price = price + (oldPrice - price) * 0.1;
317	
318	      // 4. 限制在合理范围
319	      price = Math.max(
320	        good.basePrice * 0.25,
321	        Math.min(good.basePrice * 6, price),
322	      );
323	      price = Math.round(price * 100) / 100;
324	
325	      state.trade.goodsPrices[locKey][good.id] = price;
326	    }
327	  }
328	  state.trade.lastPriceUpdate = state.player.day;
329	}
