        hair: 100,
        dignity: 60,
        upwardMgmt: 20,
        kpi: 20,
        ability: 30,
        risk: 0,
        popularity: 30,
      },

      // 阶段与时间
      phase: "street", // 'street' | 'corporate'
      day: 1,
      corpYear: 0, // 入职年数
      corpQuarter: 1, // 1-4
      timeSlot: "morning", // 'morning' | 'afternoon' | 'evening' (显示用)
      actionPoints: 100, // 当前行动力 (0-100)
      maxActionPoints: 100, // 每日行动力上限
    },

    // --- 经济 ---
    resources: {
      cash: 2000, // 现金（元）
      bankBalance: 0, // 银行存款
      debt: 5500, // 当前欠款
      loanPrincipal: 5500, // 原始借款额
      loanDay: 0, // 借款日
      dailyInterest: 0.003, // 日息 0.3%
      totalEarned: 0, // 终身总收入
    },

    // --- 基本需求 (0-100) ---
    needs: {
      hunger: 70,
      fatigue: 15,
      hygiene: 75,
      happiness: 55,
    },

    // --- 派生状态 ---
    status: {
      health: 100,
      fame: 0,
      emotionalState: "stable", // stable|happy|sad|angry|stressed|depressed
      sick: false,
      injured: false,
    },

    // --- 技能 (level: 0-100, xp: 0-1000) ---
    skills: {
      cooking: { level: 0, xp: 0 },
      repair: { level: 0, xp: 0 },
      coding: { level: 0, xp: 0 },
      english: { level: 0, xp: 0 },
      driving: { level: 0, xp: 0 },
      sales: { level: 0, xp: 0 },
      management: { level: 0, xp: 0 },
      accounting: { level: 0, xp: 0 },
      electrician: { level: 0, xp: 0 },
      welding: { level: 0, xp: 0 },
    },
    certificates: [],
    education: 0,

    // --- 物品栏 ---
    inventory: {
      items: [], // [{ id, qty, avgBuyPrice }]
      capacity: 20, // 基础容量
